static void lcm_set_util_funcs(const LCM_UTIL_FUNCS *util)
{
	memcpy(&lcm_util, util, sizeof(LCM_UTIL_FUNCS));
}

static void lcm_get_params(LCM_PARAMS *params)
{
	memset(params, 0, sizeof(LCM_PARAMS));

	params->type = LCM_TYPE_DSI;
	params->width = FRAME_WIDTH;
	params->height = FRAME_HEIGHT;
	params->physical_width = 68;
	params->physical_height = 121;

#if (LCM_DSI_CMD_MODE)
	params->dsi.mode = CMD_MODE;
#else
	params->dsi.mode = BURST_VDO_MODE;
#endif
	params->dsi.switch_mode_enable = 0;
	params->dsi.noncont_clock = TRUE;

	params->dsi.LANE_NUM = LCM_FOUR_LANE;
	params->dsi.data_format.color_order = LCM_COLOR_ORDER_RGB;
	params->dsi.data_format.trans_seq = LCM_DSI_TRANS_SEQ_MSB_FIRST;
	params->dsi.data_format.padding = LCM_DSI_PADDING_ON_LSB;
	params->dsi.data_format.format = LCM_DSI_FORMAT_RGB888;
	params->dsi.PS = LCM_PACKED_PS_24BIT_RGB888;

	params->dsi.vertical_sync_active = 2;
	params->dsi.vertical_backporch = 4;
	params->dsi.vertical_frontporch = 22;
	params->dsi.vertical_active_line = FRAME_HEIGHT;

	params->dsi.horizontal_sync_active = 4;
	params->dsi.horizontal_backporch = 72;
	params->dsi.horizontal_frontporch = 72;
	params->dsi.horizontal_active_pixel = FRAME_WIDTH;

	params->dsi.PLL_CLOCK = 475;

#ifdef TE_ENABLE_FUNCTION
	/* ESD detection through the TE line (dsi_te EINT in nikel.dts) */
	params->dsi.esd_check_enable = 1;
	params->dsi.customization_esd_check_enable = 0;
#else
	params->dsi.esd_check_enable = 1;
	params->dsi.customization_esd_check_enable = 1;
	params->dsi.lcm_esd_check_table[0].cmd = 0x0a;
	params->dsi.lcm_esd_check_table[0].count = 1;
	params->dsi.lcm_esd_check_table[0].para_list[0] = 0x9c;
#endif
}

static void tps65132_enable(int en)
{
	int num, ret;

	if (en) {
		nk_pin_set(NK_ENP, 1);
		MDELAY(12);
		nk_pin_set(NK_ENN, 1);
		MDELAY(12);

		/* VPOS / VNEG = 0x0F (5.5 V), three tries each like the original */
		for (num = 0; num < 3; num++) {
			ret = tps65132_write_bytes(0x00, 0x0f);
			if (!ret)
				break;
			MDELAY(5);
		}
		for (num = 0; num < 3; num++) {
			ret = tps65132_write_bytes(0x01, 0x0f);
			if (!ret)
				break;
			MDELAY(5);
		}
		if (ret)
			pr_err(LCD_TAG "tps65132 bias write failed (%d)\n", ret);
	} else {
		nk_pin_set(NK_ENN, 0);
		MDELAY(12);
		nk_pin_set(NK_ENP, 0);
		MDELAY(12);
	}
}

static void lcm_init(void)
{
	tps65132_enable(1);
	MDELAY(20);

	NK_RESET(1);
	MDELAY(20);
	NK_RESET(0);
	MDELAY(20);
	NK_RESET(1);
	MDELAY(50);
	NK_RESET(0);
	MDELAY(50);
	NK_RESET(1);
	MDELAY(50);

	PUSH(lcm_initialization_setting);
	MDELAY(20);
}

static void lcm_suspend(void)
{
	PUSH(lcm_suspend_setting);
	NK_RESET(0);
	MDELAY(10);
	tps65132_enable(0);
}

static void lcm_resume(void)
{
	tps65132_enable(1);
	MDELAY(15);

	NK_RESET(1);
	MDELAY(3);
	NK_RESET(0);
	MDELAY(3);
	NK_RESET(1);
	MDELAY(3);
	NK_RESET(0);
	MDELAY(3);
	NK_RESET(1);
	MDELAY(22);

	if (cabc_enable_flag == 0)
		PUSH(lcm_initialization_setting);
	else
		PUSH(lcm_cabc_on_initialization_setting);
}

static unsigned int lcm_compare_id(void)
{
	unsigned char buffer[2] = { 0 };
	unsigned int array[4];

	NK_RESET(1);
	MDELAY(1);
	NK_RESET(0);
	MDELAY(10);
	NK_RESET(1);
	MDELAY(10);

	array[0] = 0x00023700;	/* max return size 2 */
	dsi_set_cmdq(array, 1, 1);
	array[0] = 0x00ff1500;	/* page 0 */
	dsi_set_cmdq(array, 1, 1);
	array[0] = 0x01fb1500;
	dsi_set_cmdq(array, 1, 1);
	MDELAY(10);
	read_reg_v2(0xf4, buffer, 1);
	MDELAY(20);

	pr_info(LCD_TAG "chip id 0x%02x (expect 0x%02x)\n", buffer[0], LCM_ID_NT35596);
	return buffer[0] == LCM_ID_NT35596;
}

static void lcm_setbacklight_cmdq(void *handle, unsigned int level)
{
	static unsigned int last_level = 0xffff;

	if (level == last_level)
		return;
	last_level = level;

	if (level == 0) {
		nk_pin_set(NK_BL, 0);
		lcm_backlight_level_setting[0].para_list[0] = 0;
		PUSH(lcm_backlight_level_setting);
		return;
	}

	/*
	 * Stock clamps 1..3 to 3 and drives levels < 32 through the KTD3116
	 * ExpressWire bit-bang on the BL_EN pin. Not ported yet (timing), so the
	 * floor is 32 for now.
	 */
	if (level < 32)
		level = 32;
	if (level > 255)
		level = 255;

	nk_pin_set(NK_BL, 1);
	lcm_backlight_level_setting[0].para_list[0] = level;
	PUSH(lcm_backlight_level_setting);
}

LCM_DRIVER nt35596_fhd_tianma_phantom_lcm_drv = {
	.name			= "nt35596_fhd_tianma_phantom",
	.set_util_funcs		= lcm_set_util_funcs,
	.get_params		= lcm_get_params,
	.init			= lcm_init,
	.suspend		= lcm_suspend,
	.resume			= lcm_resume,
	.compare_id		= lcm_compare_id,
	.set_backlight_cmdq	= lcm_setbacklight_cmdq,
};
